<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useProjectStore } from '@/stores/project'
import { addProjectMember, getWriteKeyStatus, listProjectMembers, removeProjectMember, rotateWriteKey, updateProjectSettings, type ProjectMember, type ProjectRole, type WriteKeyStatus } from '@/api/projects'
const projects=useProjectStore();const project=computed(()=>projects.currentProject);const members=ref<ProjectMember[]>([]);const keyStatus=ref<WriteKeyStatus>({});const plaintextKey=ref('');const loading=ref(false);const error=ref('');const form=reactive({timezone:'',origins:''});const memberForm=reactive({username:'',role:'VIEWER' as ProjectRole});let controller:AbortController|undefined
async function load(){if(!project.value)return;controller?.abort();controller=new AbortController();loading.value=true;error.value='';form.timezone=project.value.timezone;form.origins=project.value.allowedOrigins.join('\n');try{[members.value,keyStatus.value]=await Promise.all([listProjectMembers(project.value.id,controller.signal),getWriteKeyStatus(project.value.id,controller.signal)])}catch(cause){if(!controller.signal.aborted)error.value=cause instanceof Error?cause.message:'设置加载失败'}finally{if(!controller.signal.aborted)loading.value=false}}
async function save(){if(!project.value||!projects.canMutate)return;loading.value=true;try{const updated=await updateProjectSettings(project.value.id,{timezone:form.timezone,allowedOrigins:form.origins.split('\n').map(v=>v.trim()).filter(Boolean)});const index=projects.projects.findIndex(v=>v.id===updated.id);const current=index>=0?projects.projects[index]:undefined;if(current)projects.projects[index]={...updated,role:current.role}}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败'}finally{loading.value=false}}
async function add(){if(!project.value)return;error.value='';try{await addProjectMember(project.value.id,memberForm.username.trim(),memberForm.role);memberForm.username='';await load()}catch(cause){error.value=cause instanceof Error?cause.message:'成员保存失败'}}
async function remove(member:ProjectMember){if(!project.value)return;error.value='';try{await removeProjectMember(project.value.id,member.user_id);await load()}catch(cause){error.value=cause instanceof Error?cause.message:'成员移除失败'}}
async function rotate(){if(!project.value)return;error.value='';try{const result=await rotateWriteKey(project.value.id);plaintextKey.value=result.write_key;keyStatus.value={previous_key_expires_at:result.previous_key_expires_at}}catch(cause){error.value=cause instanceof Error?cause.message:'密钥轮换失败'}}
watch(()=>projects.currentProjectId,load,{immediate:true});onBeforeUnmount(()=>controller?.abort())
</script>
<template><section aria-labelledby="settings-title"><header class="page-heading"><div><p class="eyebrow">PROJECT SETTINGS</p><h1 id="settings-title">项目设置</h1><p>管理统计时区、Web Origin、成员与写入密钥。</p></div></header><div v-if="error" class="page-error" role="alert">{{error}}</div>
  <article class="overview-card"><h2>基础设置</h2><el-form label-position="top" @submit.prevent="save"><el-form-item label="项目时区"><el-input v-model="form.timezone"/></el-form-item><el-form-item label="允许的 Web Origins（每行一个）"><el-input v-model="form.origins" type="textarea" :rows="4"/></el-form-item><el-button native-type="submit" type="primary" :loading="loading">保存设置</el-button></el-form></article>
  <article class="overview-card"><h2>项目成员</h2><el-form class="inline-settings" @submit.prevent="add"><el-input v-model="memberForm.username" placeholder="已存在账号用户名"/><el-select v-model="memberForm.role"><el-option label="管理员" value="ADMIN"/><el-option label="只读" value="VIEWER"/></el-select><el-button native-type="submit" type="primary" :disabled="!memberForm.username.trim()">添加或更新</el-button></el-form><el-table :data="members"><el-table-column prop="username" label="用户名"/><el-table-column prop="display_name" label="显示名"/><el-table-column prop="role" label="角色"/><el-table-column label="操作"><template #default="scope"><el-button type="danger" link @click="remove(scope.row)">移除</el-button></template></el-table-column></el-table></article>
  <article class="overview-card"><h2>写入密钥</h2><el-alert v-if="keyStatus.previous_key_expires_at" type="warning" :closable="false" :title="`旧密钥仍可使用至 ${new Date(keyStatus.previous_key_expires_at).toLocaleString()}（轮换后最多 24 小时）`"/><p>服务端只保存哈希，当前密钥无法再次查看。轮换后新密钥只显示一次。</p><el-button type="danger" @click="rotate">轮换写入密钥</el-button><div v-if="plaintextKey" class="write-key-box" role="status"><strong>请立即保存，新密钥关闭页面后不再显示</strong><code>{{plaintextKey}}</code><el-button @click="plaintextKey=''">已保存并隐藏</el-button></div></article>
</section></template>
